args.command:
cd /bench/repo && find . -name '*.go' -not -path './web/*' > /tmp/allgo.txt && wc -l /tmp/allgo.txt && perl -e '
my @names;
open(D,"/tmp/decls.txt"); while(<D>){ chomp; my @f=split /\t/; push @names, [$f[0],$f[1],$f[2],$f[3]//""]; } close D;
my %seen; my @uniq;
for my $n (@names){ my $k=$n->[1]; push @uniq,$k unless $seen{$k}++; }
# load all files
my %content;
open(F,"/tmp/allgo.txt"); my @files=<F>; close F; chomp @files;
for my $f (@files){ local $/; open(my $fh,"<",$f) or next; my $c=<$fh>; close $fh; $content{$f}=$c; }
for my $name (@uniq){
  my ($unq,$sel)=(0,0);
  for my $f (keys %content){
    my $c=$content{$f};
    # remove func declaration lines
    my @lines=split /\n/,$c;
    for my $l (@lines){
      next if $l=~/^func\s/;
      my $t=$l;
      my $u=()= $t=~/(?<![\w.\x22])\Q$name\E\s*\(/g;
      my $s=()= $t=~/\.\Q$name\E\s*\(/g;
      $unq+=$u; $sel+=$s;
    }
  }
  printf "%d\t%d\t%d\t%s\n",$unq+$sel,$unq,$sel,$name;
}
' | sort -rn > /tmp/counts.txt; head -40 /tmp/counts.txt

