args.command:
cd /bench/repo && cat > /tmp/fanin.pl <<'EOF'
my $name=$ARGV[0]; shift @ARGV;
open(F,"/tmp/allgo.txt"); my @files=<F>; close F; chomp @files;
my ($tot,$prod,$test)=(0,0,0); my (%callers,%prodcallers,%pkgs);
for my $f (@files){
  open(my $fh,"<",$f) or next; my @lines=<$fh>; close $fh;
  my $cur="(top)";
  for my $l (@lines){
    if($l=~/^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)/){ $cur=($1? "($1) ":"").$2; next; }
    my $n=()= $l=~/(?<![\w.\x22])\Q$name\E\s*\(/g;
    my $s=()= $l=~/\.\Q$name\E\s*\(/g;
    my $c=$n+$s;
    next unless $c;
    $tot+=$c; $callers{"$f::$cur"}+=$c; $pkgs{$f}+=$c;
    if($f=~/_test\.go$/){ $test+=$c } else { $prod+=$c; $prodcallers{"$f::$cur"}+=$c }
  }
}
printf "%-22s total=%-4d prod=%-4d test=%-4d distinctCallers=%-4d prodDistinctCallers=%-3d files=%d\n",$name,$tot,$prod,$test,scalar(keys %callers),scalar(keys %prodcallers),scalar(keys %pkgs);
EOF
for n in CompileToStatement NewEngine NewSchema GenUUID addArg Compile Field Register Validate DefaultEngine renderChildren jsonArrayExpr matches getConstValue; do perl /tmp/fanin.pl $n; done

